<style>
.linear-trip-registry.is-service-grid td{vertical-align:top}
.linear-trip-registry .trip-service-name{font-weight:700}.linear-trip-registry .trip-service-desc{white-space:normal;line-height:1.35}.linear-trip-registry .trip-service-secondary{display:block;color:var(--muted,#667085);font-size:12px;margin-top:3px}.linear-trip-registry .trip-common-cell{vertical-align:middle!important}.linear-trip-services-section{margin-top:18px}.linear-trip-service-card{border:1px solid var(--border,#d8dee8);border-radius:10px;padding:14px;margin:10px 0;background:var(--surface,#fff)}.linear-trip-service-card-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.linear-trip-service-card-title{font-weight:700}.linear-trip-service-fields{display:grid;grid-template-columns:minmax(180px,1fr) minmax(220px,1.3fr);gap:12px}.linear-trip-service-fields .service-description{grid-column:1/-1}.linear-trip-service-payments{margin-top:12px}.linear-trip-service-payments .linear-trip-payment-row{margin-top:8px}.trip-services-view{border-top:1px solid var(--border,#e5e7eb);margin-top:18px;padding-top:16px;max-width:100%;min-width:0;box-sizing:border-box}.trip-services-view-card{padding:10px 0;border-bottom:1px solid var(--border,#eef0f3);max-width:100%;overflow-wrap:anywhere}.trip-services-view-name{font-weight:700}.trip-services-view-meta{color:var(--muted,#667085);margin-top:4px}.trip-services-view-payments{margin-top:6px;font-size:13px}@media(max-width:900px){.linear-trip-service-fields{grid-template-columns:1fr}}
</style>
<script>
(function(){
'use strict';
var endpoint=<?= json_encode(app_url('/company/trips/linear/service-lines'), JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
var cache={};
function esc(v){var d=document.createElement('div');d.textContent=v==null?'':String(v);return d.innerHTML}
function money(v){var n=Number(String(v||0).replace(',','.'));return isFinite(n)?new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(n)+' ₽':'—'}
function fetchServices(ids){ids=(ids||[]).filter(Boolean);if(!ids.length)return Promise.resolve({});return fetch(endpoint+'?route_ids='+encodeURIComponent(ids.join(',')),{credentials:'same-origin',headers:{Accept:'application/json'}}).then(function(r){return r.json()}).then(function(j){if(j&&j.success){Object.assign(cache,j.services_by_route||{});return j.services_by_route||{}}return {}}).catch(function(){return {}})}
function paymentText(p){var parts=[money(p.amount)];if(p.condition_type){var labels={prepayment:'Предоплата',start_day:'В день загрузки',after_start:'После загрузки',end_day:'В день выгрузки',after_end:'После выгрузки',after_documents:'Документы получены',specific_date:'Конкретная дата'};parts.push(labels[p.condition_type]||p.condition_type)}if(Number(p.days_count)>0)parts.push(p.days_count+' '+(p.days_kind==='working'?'РД':'КД'));return parts.join(' · ')}
function rebuildRegistry(){var table=document.querySelector('.linear-trip-registry');if(!table||table.dataset.servicesReady==='1')return;var body=table.tBodies[0];if(!body)return;var source=Array.from(body.querySelectorAll('tr[data-linear-route-id]'));var ids=source.map(function(r){return r.dataset.linearRouteId});fetchServices(ids).then(function(){var hasAdditionalServices=ids.some(function(id){return (cache[id]||[]).length>0});if(!hasAdditionalServices){table.dataset.servicesReady='1';return}var frag=document.createDocumentFragment();source.forEach(function(row){var c=Array.from(row.cells);if(c.length<9){frag.appendChild(row);return}var routeId=row.dataset.linearRouteId;var extras=cache[routeId]||[];if(!extras.length){frag.appendChild(row);return}var total=1+extras.length;var primary=document.createElement('tr');primary.dataset.linearRouteId=routeId;primary.dataset.erpSortDate=row.dataset.erpSortDate||routeId;for(var commonIndex=0;commonIndex<4;commonIndex++){var common=c[commonIndex].cloneNode(true);common.rowSpan=total;common.classList.add('trip-common-cell');primary.appendChild(common)}for(var primaryIndex=4;primaryIndex<9;primaryIndex++)primary.appendChild(c[primaryIndex].cloneNode(true));frag.appendChild(primary);extras.forEach(function(s){var tr=document.createElement('tr');tr.dataset.linearRouteId=routeId;tr.dataset.erpSortDate=row.dataset.erpSortDate||routeId;var payments=s.payments||[];var totalAmount=payments.reduce(function(sum,p){return sum+Number(String(p.amount||0).replace(',','.'))},0);var executor=document.createElement('td');executor.className='registry-executor';executor.innerHTML='<span class="registry-executor-line">'+esc(s.contractor_name||'—')+'</span>';var details=document.createElement('td');details.className='registry-route trip-service-desc';details.innerHTML=(s.service_name?'<span class="registry-route-line"><strong>'+esc(s.service_name)+'</strong></span>':'')+(s.description?'<span class="registry-route-line registry-executor-secondary">'+esc(s.description)+'</span>':'')||'<span class="registry-empty">—</span>';var cargo=document.createElement('td');cargo.className='registry-cargo';cargo.innerHTML='<span class="registry-empty">—</span>';var customerRate=document.createElement('td');customerRate.className='registry-rate';customerRate.innerHTML='<span class="registry-empty">—</span>';var serviceRate=document.createElement('td');serviceRate.className='registry-rate';serviceRate.innerHTML=payments.length?'<span class="registry-rate-total">'+money(totalAmount)+'</span>'+payments.map(function(p){return '<span class="registry-payment-line">'+esc(paymentText(p))+'</span>'}).join(''):'<span class="registry-empty">—</span>';tr.appendChild(executor);tr.appendChild(details);tr.appendChild(cargo);tr.appendChild(customerRate);tr.appendChild(serviceRate);frag.appendChild(tr)});});body.replaceChildren(frag);table.classList.add('is-service-grid');table.dataset.servicesReady='1'})}
function renumber(container,serviceIndex){Array.from(container.querySelectorAll('[data-service-payment-row]')).forEach(function(row,pi){row.querySelectorAll('[name]').forEach(function(el){el.name=el.name.replace(/trip_services\[\d+\]\[payments\]\[\d+\]/,'trip_services['+serviceIndex+'][payments]['+pi+']')})})}
function dispatchFieldChange(input){input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}))}
function ensureServiceDaysStepper(row){if(!row)return null;var field=row.querySelector('[data-days-count-wrapper]');if(!field)return null;var input=field.querySelector('input[name$="[days_count]"]');if(!input)return null;var existing=input.closest('.linear-trip-days-stepper');if(existing)return input;var stepper=document.createElement('div');stepper.className='linear-trip-days-stepper';stepper.setAttribute('data-service-days-stepper','');var minus=document.createElement('button');minus.type='button';minus.textContent='−';minus.setAttribute('data-service-days-minus','');minus.setAttribute('aria-label','Уменьшить количество дней');var plus=document.createElement('button');plus.type='button';plus.textContent='+';plus.setAttribute('data-service-days-plus','');plus.setAttribute('aria-label','Увеличить количество дней');input.parentNode.insertBefore(stepper,input);stepper.appendChild(minus);stepper.appendChild(input);stepper.appendChild(plus);function current(){var n=parseInt(input.value,10);return Number.isFinite(n)&&n>0?n:3}minus.addEventListener('click',function(){input.value=String(Math.max(1,current()-1));dispatchFieldChange(input)});plus.addEventListener('click',function(){input.value=String(current()+1);dispatchFieldChange(input)});return input}
function syncServiceDueFields(row){if(!row)return;var cond=row.querySelector('[data-condition-type]');if(!cond)return;var val=cond.value;var showDays=val==='after_start'||val==='after_end'||val==='after_documents';var showSpecific=val==='prepayment'||val==='specific_date';var days=row.querySelector('[data-days-count-wrapper]');var kind=row.querySelector('[data-days-kind-wrapper]');var spec=row.querySelector('[data-specific-date-wrapper]');var daysInput=ensureServiceDaysStepper(row);var kindInput=kind?kind.querySelector('select[name$="[days_kind]"]'):null;if(days)days.classList.toggle('is-hidden',!showDays);if(kind)kind.classList.toggle('is-hidden',!showDays);if(spec)spec.classList.toggle('is-hidden',!showSpecific);if(daysInput){daysInput.required=showDays;if(showDays&&String(daysInput.value||'').trim()==='')daysInput.value='3';if(!showDays)daysInput.value=''}if(kindInput){kindInput.required=showDays;if(!showDays)kindInput.value=''}}
function bindServicePaymentList(list){if(!list||list.dataset.servicePaymentUiReady==='1')return;list.dataset.servicePaymentUiReady='1';Array.from(list.querySelectorAll('[data-service-payment-row]')).forEach(syncServiceDueFields);list.addEventListener('change',function(e){if(e.target.matches('[data-condition-type]'))syncServiceDueFields(e.target.closest('[data-service-payment-row]'))});list.addEventListener('click',function(e){var remove=e.target.closest('[data-remove-payment-row]');if(!remove)return;var row=remove.closest('[data-service-payment-row]');if(!row)return;if(list.querySelectorAll('[data-service-payment-row]').length<=1)return;row.remove();renumber(list,Number(list.dataset.serviceIndex||0))})}
function makePaymentRow(serviceIndex,pi,data){var source=document.querySelector('[data-payment-container="carrier_payments"] [data-payment-row]');var row=source?source.cloneNode(true):document.createElement('div');if(!source){row.className='linear-trip-payment-row';row.innerHTML='<div class="field"><label class="field-label">Сумма *</label><input class="field-input" name="x[amount]"></div><div class="field"><label class="field-label">Срок оплаты *</label><select class="field-input" name="x[condition_type]" data-condition-type><option value="">— Выберите срок —</option></select></div>'}row.setAttribute('data-service-payment-row','');row.removeAttribute('data-payment-row');row.querySelectorAll('[name]').forEach(function(el){var suffix=(el.name.match(/\[([^\]]+)\]$/)||[])[1]||'';el.name='trip_services['+serviceIndex+'][payments]['+pi+']['+suffix+']';if(el.tagName==='SELECT')el.selectedIndex=0;else el.value=''});var map=data||{};row.querySelectorAll('[name]').forEach(function(el){var key=(el.name.match(/\[([^\]]+)\]$/)||[])[1];if(key&&map[key]!=null){el.value=String(map[key]).replace(/\.00$/,'')}});var remove=row.querySelector('[data-remove-payment-row]');if(remove){remove.classList.remove('is-hidden');remove.onclick=null}syncServiceDueFields(row);return row}
function serviceCard(form,service,index,finance){var card=document.createElement('div');card.className='linear-trip-service-card';card.dataset.tripServiceCard='';card.innerHTML='<div class="linear-trip-service-card-head"><div class="linear-trip-service-card-title">Дополнительная услуга</div><button type="button" class="linear-trip-row-remove" data-remove-service>×</button></div><input type="hidden" name="trip_services['+index+'][id]" value="'+(service.id||'')+'"><div class="linear-trip-service-fields"><div class="field"><label class="field-label">Услуга <span class="req">*</span></label><input class="field-input" name="trip_services['+index+'][service_name]" value="'+esc(service.service_name||'')+'" placeholder="Например: Кран"></div><div class="field"><label class="field-label">Подрядчик <span class="req">*</span></label><select class="field-input" name="trip_services['+index+'][contractor_id]" data-service-contractor></select></div><div class="field service-description"><label class="field-label">Описание услуги</label><input class="field-input" name="trip_services['+index+'][description]" value="'+esc(service.description||'')+'" placeholder="Например: кран 25 т, 4 часа"></div></div>';var contractorSource=form.querySelector('select[name="carrier_contractor_id"]');var select=card.querySelector('[data-service-contractor]');if(contractorSource)select.innerHTML=contractorSource.innerHTML;select.value=service.contractor_id||'';if(finance){var box=document.createElement('div');box.className='linear-trip-service-payments';box.innerHTML='<div class="linear-trip-block-head"><div class="linear-trip-block-title">Оплаты подрядчику</div><button type="button" class="btn btn-ghost" data-add-service-payment>+ Добавить оплату</button></div><div data-service-payments></div>';card.appendChild(box);var list=box.querySelector('[data-service-payments]');list.dataset.serviceIndex=String(index);var payments=(service.payments&&service.payments.length)?service.payments:[{}];payments.forEach(function(p,pi){list.appendChild(makePaymentRow(index,pi,p))});bindServicePaymentList(list);box.querySelector('[data-add-service-payment]').onclick=function(){var currentIndex=Number(list.dataset.serviceIndex||0);var row=makePaymentRow(currentIndex,list.querySelectorAll('[data-service-payment-row]').length,{});list.appendChild(row);syncServiceDueFields(row);renumber(list,currentIndex)}}card.querySelector('[data-remove-service]').onclick=function(){card.remove();renumberServices(form)};return card}
function renumberServices(form){var cards=Array.from(form.querySelectorAll('[data-trip-service-card]'));cards.forEach(function(card,si){card.querySelectorAll('[name]').forEach(function(el){el.name=el.name.replace(/trip_services\[\d+\]/,'trip_services['+si+']')});var list=card.querySelector('[data-service-payments]');if(list){list.dataset.serviceIndex=String(si);renumber(list,si)}})}
function enhanceForm(form){if(!form||form.dataset.tripServicesReady==='1')return;form.dataset.tripServicesReady='1';var finance=!!form.querySelector('[data-payment-container="carrier_payments"]');var section=document.createElement('div');section.className='linear-trip-services-section';section.innerHTML='<div class="section-title">Услуги / исполнители</div><div class="linear-trip-service-card"><div class="linear-trip-service-card-title">Основная услуга: Перевозка</div><div class="field-msg">Исполнитель и оплаты основной перевозки задаются существующими полями рейса выше.</div></div><div data-trip-services-list></div><button type="button" class="btn btn-ghost" data-add-trip-service>+ Добавить услугу</button>';var comment=Array.from(form.querySelectorAll('.section-title')).find(function(x){return x.textContent.trim()==='Комментарий'});var anchor=comment||form.querySelector('.linear-trip-layout-docs');if(anchor&&anchor.parentNode)anchor.parentNode.insertBefore(section,anchor);else (form.querySelector('.linear-trip-layout-main')||form).appendChild(section);var list=section.querySelector('[data-trip-services-list]');var match=form.action.match(/\/linear\/(\d+)\/modal-edit/);var routeId=match?match[1]:null;function fill(items){(items||[]).forEach(function(s,i){list.appendChild(serviceCard(form,s,i,finance))})}if(routeId){fetchServices([routeId]).then(function(){fill(cache[routeId]||[])})}section.querySelector('[data-add-trip-service]').onclick=function(){var i=list.querySelectorAll('[data-trip-service-card]').length;list.appendChild(serviceCard(form,{},i,finance))}}
function enhanceView(root){var marker=root.querySelector&&root.querySelector('[data-trip-view-title]');if(!marker||root.querySelector('.trip-services-view'))return;var m=(marker.getAttribute('data-trip-view-title')||'').match(/#(\d+)/);if(!m)return;fetchServices([m[1]]).then(function(){var items=cache[m[1]]||[];var box=document.createElement('div');box.className='trip-services-view';box.innerHTML='<div class="section-title">Дополнительные услуги</div>'+(items.length?items.map(function(s){return '<div class="trip-services-view-card"><div class="trip-services-view-name">'+esc(s.service_name)+' · '+esc(s.contractor_name)+'</div><div class="trip-services-view-meta">'+esc(s.description||'—')+'</div>'+(s.payments&&s.payments.length?'<div class="trip-services-view-payments">'+s.payments.map(function(p){return esc(paymentText(p))}).join('<br>')+'</div>':'')+'</div>'}).join(''):'<div class="field-msg">Дополнительных услуг нет.</div>');var body=marker.closest('.modal-body')||root;var main=body.querySelector('.driver-modal-main')||body;main.appendChild(box)})}
function scan(root){(root.querySelectorAll?root.querySelectorAll('[data-linear-trip-form]'):[]).forEach(enhanceForm);enhanceView(root)}
document.addEventListener('DOMContentLoaded',function(){rebuildRegistry();scan(document);new MutationObserver(function(ms){ms.forEach(function(m){m.addedNodes.forEach(function(n){if(n.nodeType===1){if(n.matches&&n.matches('[data-linear-trip-form]'))enhanceForm(n);scan(n)}})})}).observe(document.body,{childList:true,subtree:true})});
})();
</script>
